cat > zz_heldout_test.go <<'EOF'
package shop

import (
	"errors"
	"strings"
	"testing"
)

func TestHeldoutPriceLineWraps(t *testing.T) {
	_, err := PriceLine(Catalog{}, Line{SKU: "nope", Qty: 1})
	if err == nil || !strings.HasPrefix(err.Error(), "shop: ") || errors.Unwrap(err) == nil {
		t.Fatalf("PriceLine error = %v; want a wrapped error starting with \"shop: \"", err)
	}
}
EOF
go test -count=1 -run Heldout ./...; rc=$?; rm -f zz_heldout_test.go; exit $rc
